import {
  GetCommand,
  PutCommand,
  UpdateCommand,
  QueryCommand,
  DeleteCommand,
  BatchGetCommand,
  QueryCommandInput,
  UpdateCommandInput,
  TransactWriteCommand,

  type GetCommandOutput,
  type PutCommandOutput,
  type UpdateCommandOutput,
  type DeleteCommandOutput,
  type QueryCommandOutput,
  type BatchGetCommandOutput,
  type TransactWriteCommandInput,
  type TransactWriteCommandOutput,
} from "@aws-sdk/lib-dynamodb";


import { ddbDocClient } from "../configs/db.config";
import { sendDoc } from "../configs/dynamodb-send";
import {
  createLogger,
  createChildLogger,
} from '@api-hub/observability';
import { ConditionalWriteConflictError } from "../errors/app.error";
import {
  getTransactCancellationReasons,
  hasTransactConditionalFailure,
  transactConditionalFailureIndexes,
} from "./transact-write-errors";

const baseLogger = createLogger({
  service: "dynamo-repository",
  redactPII: true,
});

export abstract class BaseRepository {

  private readonly logger = createChildLogger(baseLogger, {
    service: this.constructor.name,
  });

  protected async get<T>(table: string, key: any): Promise<T | null> {

    this.logger.debug({ event: "dynamodb_get", table, key });

    const result = await sendDoc<GetCommandOutput>(
      ddbDocClient,
      new GetCommand({
        TableName: table,
        Key: key,
      })
    );

    return (result.Item as T) || null;

  }

  protected async transactWrite(
    params: TransactWriteCommandInput
  ): Promise<void> {

    this.logger.debug({
      event: 'dynamodb_transact_write',
      itemCount: params.TransactItems?.length,
    });

    try {
      await sendDoc<TransactWriteCommandOutput>(
        ddbDocClient,
        new TransactWriteCommand(params),
      );

      this.logger.info({
        event: 'dynamodb_transact_write_success',
        itemCount: params.TransactItems?.length,
      });
    } catch (err: unknown) {
      if (hasTransactConditionalFailure(err)) {
        const failedTransactItemIndexes = transactConditionalFailureIndexes(err);

        this.logger.warn({
          event: 'dynamodb_transact_conditional_failed',
          itemCount: params.TransactItems?.length,
          failedTransactItemIndexes,
        });

        throw new ConditionalWriteConflictError(err, {
          cancellationReasons: getTransactCancellationReasons(err),
          failedTransactItemIndexes,
        });
      }

      this.logger.error({
        event: 'dynamodb_transact_write_failed',
        itemCount: params.TransactItems?.length,
        error: err instanceof Error ? err.message : String(err),
      });

      throw err;
    }
  }

  protected async put<T>(
    table: string,
    item: T,
    condition?: string
  ): Promise<void> {
  
    this.logger.debug({
      event: "dynamodb_put_attempt",
      table,
      hasCondition: !!condition,
    });
  
    try {
  
      await sendDoc<PutCommandOutput>(
        ddbDocClient,
        new PutCommand({
          TableName: table,
          Item: item as Record<string, any>,
          ConditionExpression: condition,
        })
      );
  
      this.logger.info({
        event: "dynamodb_put_success",
        table,
      });
  
    } catch (err: any) {
  
      if (err.name === "ConditionalCheckFailedException") {
  
        this.logger.warn({
          event: "dynamodb_conditional_check_failed",
          table,
          reason: "conditional_expression_failed",
        });
  
        // 👇 IMPORTANT: rethrow a DOMAIN-SAFE error
        throw new ConditionalWriteConflictError(err);
  
      }
  
      this.logger.error({
        event: "dynamodb_put_failed",
        table,
        error: err.message,
      });
  
      throw err;
    }
  }

  protected async update(params: UpdateCommandInput): Promise<void> {

    this.logger.debug({
      event: "dynamodb_update",
      table: params?.TableName,
      key: params?.Key,
    });

    await sendDoc<UpdateCommandOutput>(
      ddbDocClient,
      new UpdateCommand(params)
    );

  }

  protected async delete(
    table: string,
    key: any
  ): Promise<void> {

    this.logger.debug({ event: "dynamodb_delete", table, key });

    await sendDoc<DeleteCommandOutput>(
      ddbDocClient,
      new DeleteCommand({
        TableName: table,
        Key: key,
      })
    );

  }

  protected async query<T>(
    params: QueryCommandInput
  ): Promise<T[]> {

    this.logger.debug({
      event: "dynamodb_query",
      table: params?.TableName,
      index: params?.IndexName,
    });

    const result = await sendDoc<QueryCommandOutput>(
      ddbDocClient,
      new QueryCommand(params)
    );

    return (result.Items as T[]) || [];

  }

  /** Single DynamoDB Query page; preserves {@link QueryCommandOutput.LastEvaluatedKey} for pagination. */
  protected async queryPage<T>(
    params: QueryCommandInput
  ): Promise<{ items: T[]; lastEvaluatedKey?: Record<string, unknown> }> {

    this.logger.debug({
      event: "dynamodb_query_page",
      table: params?.TableName,
      index: params?.IndexName,
    });

    const result = await sendDoc<QueryCommandOutput>(
      ddbDocClient,
      new QueryCommand(params)
    );

    return {
      items: (result.Items as T[]) || [],
      lastEvaluatedKey: result.LastEvaluatedKey as Record<string, unknown> | undefined,
    };

  }

  protected async queryAll<T>(
    params: QueryCommandInput
  ): Promise<T[]> {

    const items: T[] = [];
    let lastKey;

    do {

      const result: QueryCommandOutput = await sendDoc<QueryCommandOutput>(
        ddbDocClient,
        new QueryCommand({
          ...params,
          ExclusiveStartKey: lastKey as any,
        })
      );

      if (result.Items) {
        items.push(...(result.Items as T[]));
      }

      lastKey = result.LastEvaluatedKey;

    } while (lastKey);

    return items;

  }

  protected async queryOne<T>(
    params: QueryCommandInput
  ): Promise<T | null> {

    const items = await this.query<T>({
      ...params,
      Limit: 1,
    });

    return items.length ? items[0] : null;

  }

  protected async batchGet<T>(
    params: any
  ): Promise<T[]> {

    const result = await sendDoc<BatchGetCommandOutput>(
      ddbDocClient,
      new BatchGetCommand(params)
    );

    return result.Responses
      ? (Object.values(result.Responses).flat() as T[])
      : [];

  }

}